fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping digit chars to their good counts.
    // We can use a match for clarity and direct mapping.
    fn good_count(digit: char) -> u32 {
        match digit {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0 // for completeness, won't happen given problem constraints
        }
    }

    // Extract the first two digits from input.
    let d1 = input[0];
    let d2 = input[1];

    let product = good_count(d1) * good_count(d2); // guaranteed 1..=49

    // Convert product to string representation.
    let mut output = product.to_string().chars().collect::<Vec<char>>();
    output.push('\n');

    output
}